func readReferenceLayouts(ctx context.Context, tx pgx.Tx, tenant string, got referenceState) error {
	return queryEachRow(ctx, tx, `SELECT v.cable_id,v.device_id,v.bin_id,v.operation,v.event_id,v.occurred_at,v.cable_version,
 COALESCE(jsonb_agg(jsonb_build_object('sensor_id',s.sensor_id,'position',s.position,'label',s.label,'depth_m',s.depth_m) ORDER BY s.position) FILTER (WHERE s.sensor_id IS NOT NULL),'[]'::jsonb)
 FROM cable_layout_versions v LEFT JOIN cable_layout_sensors s ON s.tenant_id=v.tenant_id AND s.cable_id=v.cable_id AND s.cable_version=v.cable_version
 WHERE v.tenant_id=$1 GROUP BY v.tenant_id,v.cable_id,v.device_id,v.bin_id,v.operation,v.event_id,v.occurred_at,v.cable_version`, func(rows pgx.Rows) error {
		var cableID string
		var cable referenceCable
		var occurred time.Time
		var raw []byte
		if err := rows.Scan(&cableID, &cable.Device, &cable.Bin, &cable.Operation, &cable.Event, &occurred, &cable.Version, &raw); err != nil {
			return err
		}
		cable.Occurred = formatReferenceTime(occurred)
		var sensors any
		if err := json.Unmarshal(raw, &sensors); err != nil {
			return err
		}
		canonical, err := canonicalJSON(sensors)
		if err != nil {
			return err
		}
		cable.Sensors = canonical
		got.CableLayouts[fmt.Sprintf("%s/%d", cableID, cable.Version)] = cable
		return nil
	}, tenant)
}

func readReferencePolicies(ctx context.Context, tx pgx.Tx, tenant string, got referenceState) error {
	return queryEachRow(ctx, tx, `SELECT policy_id,grain_type,COALESCE(bin_id::text,''),effective_from,effective_to,status,event_id,policy_version,calibrated,
 measurement_thresholds,risk_thresholds,provenance,COALESCE(calibration_evidence,''),COALESCE(approved_by,''),approved_at,supersedes_policy_id,supersedes_version
 FROM risk_policy_versions WHERE tenant_id=$1`, func(rows pgx.Rows) error {
		var policy referencePolicy
		var from time.Time
		var to *time.Time
		var thresholds, risk, provenance []byte
		var approvedAt *time.Time
		var supersedesID, supersedesVersion *string
		if err := rows.Scan(&policy.PolicyID, &policy.Grain, &policy.Bin, &from, &to, &policy.Status, &policy.Event, &policy.Version, &policy.Calibrated,
			&thresholds, &risk, &provenance, &policy.Evidence, &policy.ApprovedBy, &approvedAt, &supersedesID, &supersedesVersion); err != nil {
			return err
		}
		policy.EffectiveFrom = formatReferenceTime(from)
		if to != nil {
			policy.EffectiveTo = formatReferenceTime(*to)
		}
		var value any
		if err := json.Unmarshal(thresholds, &value); err != nil {
			return err
		}
		policy.Thresholds, _ = canonicalJSON(value)
		if err := json.Unmarshal(risk, &value); err != nil {
			return err
		}
		policy.RiskThresholds, _ = canonicalJSON(value)
		if err := json.Unmarshal(provenance, &value); err != nil {
			return err
		}
		policy.Provenance, _ = canonicalJSON(value)
		if approvedAt != nil {
			policy.ApprovedAt = formatReferenceTime(*approvedAt)
		}
		if supersedesID != nil {
			policy.SupersedesID = *supersedesID
		}
		if supersedesVersion != nil {
			policy.SupersedesVersion = fmt.Sprint(*supersedesVersion)
		}
		got.Policies[policy.PolicyID+"/"+fmt.Sprint(policy.Version)] = policy
		return nil
	}, tenant)
}

func readReferenceAssessments(ctx context.Context, tx pgx.Tx, tenant string, got referenceState) error {
	return queryEachRow(ctx, tx, `SELECT assessment_id,device_id,reading_id,source_event_id,bin_id,lot_id,grain_type,COALESCE(policy_id::text,''),severity,event_id,occurred_at,
 assessment_version,policy_version,policy_calibrated,score,reasons,policy_provenance,alert_eligible
 FROM risk_assessments WHERE tenant_id=$1`, func(rows pgx.Rows) error {
		var assessment referenceAssessment
		var occurred time.Time
		var calibrated *bool
		var score *int32
		var reasons, provenance []byte
		if err := rows.Scan(&assessment.ID, &assessment.Device, &assessment.Reading, &assessment.Source, &assessment.Bin, &assessment.Lot, &assessment.Grain, &assessment.PolicyID, &assessment.Severity, &assessment.Event, &occurred,
			&assessment.Version, &assessment.PolicyVersion, &calibrated, &score, &reasons, &provenance, &assessment.AlertEligible); err != nil {
			return err
		}
		assessment.Occurred = formatReferenceTime(occurred)
		if calibrated != nil {
			assessment.Calibrated = *calibrated
		}
		if score != nil {
			n := int64(*score)
			assessment.Score = &n
		}
		var value any
		if err := json.Unmarshal(reasons, &value); err != nil {
			return err
		}
		assessment.Reasons, _ = canonicalJSON(value)
		if len(provenance) > 0 {
			if err := json.Unmarshal(provenance, &value); err != nil {
				return err
			}
			assessment.Provenance, _ = canonicalJSON(value)
		}
		got.Assessments[assessment.ID] = assessment
		return nil
	}, tenant)
}

func readReferenceSensors(ctx context.Context, tx pgx.Tx, tenant string, historyCutoff time.Time, got referenceState) error {
	return queryEachRow(ctx, tx, `SELECT r.reading_id,r.device_id,COALESCE(r.bin_id::text,''),r.cable_id,r.sensor_id,COALESCE(layout.label,''),r.metric,r.unit,r.observed_at,r.received_at,r.stream_version,r.layout_version,r.position,r.depth_m,r.value
	FROM sensor_reading_history r LEFT JOIN cable_layout_sensors layout ON layout.tenant_id=r.tenant_id AND layout.cable_id=r.cable_id AND layout.cable_version=r.layout_version AND layout.sensor_id=r.sensor_id
	WHERE r.tenant_id=$1 AND r.observed_at >= $2`, func(rows pgx.Rows) error {
		var sensor referenceSensor
		var observed, received time.Time
		if err := rows.Scan(&sensor.Reading, &sensor.Device, &sensor.Bin, &sensor.Cable, &sensor.Sensor, &sensor.Label, &sensor.Metric, &sensor.Unit, &observed, &received, &sensor.Version, &sensor.LayoutVersion, &sensor.Position, &sensor.Depth, &sensor.Value); err != nil {
			return err
		}
		sensor.Observed = formatReferenceTime(observed)
		sensor.Received = formatReferenceTime(received)
		got.Sensors[fmt.Sprintf("%s/%s/%s", sensor.Reading, sensor.Sensor, sensor.Metric)] = sensor
		return nil
	}, tenant, historyCutoff)
}

func readReferenceNotifications(ctx context.Context, tx pgx.Tx, tenant string, got referenceState) error {
	return queryEachRow(ctx, tx, `SELECT event_id,resource_id,resource_type,purpose FROM projection_notifications WHERE tenant_id=$1`, func(rows pgx.Rows) error {
		var event, device, resourceType, purpose string
		if err := rows.Scan(&event, &device, &resourceType, &purpose); err != nil {
			return err
		}
		if resourceType != "device" || purpose != "projection_changed" {
			return errors.New("unexpected projection notification semantics")
		}
		got.Notifications[event] = device
		return nil
	}, tenant)
}
